import "dotenv/config";
import { rotateTokenPage } from "../src/lib/token-rotation";
import { db } from "../src/lib/db";
async function main() {
  const args = process.argv.slice(2);
  if (args.some((a) => a !== "--apply" && !a.startsWith("--after=")))
    throw new Error();
  let cursor = args.find((a) => a.startsWith("--after="))?.slice(8);
  do {
    const page = await rotateTokenPage({
      apply: args.includes("--apply"),
      after: cursor,
    });
    console.info(
      JSON.stringify({
        event: "token-rotation",
        mode: args.includes("--apply") ? "apply" : "dry-run",
        ...page,
      }),
    );
    if (page.failed) {
      process.exitCode = 1;
      break;
    }
    cursor = page.cursor ?? undefined;
  } while (cursor);
}
main()
  .catch(() => {
    console.error("TOKEN_ROTATION_FAILED");
    process.exitCode = 1;
  })
  .finally(() => db.$disconnect());
